231		if err != nil {
232			t.Fatalf("合法 Unicode 文本不应被拒绝: %v", err)
233		}
234		if smp.ID != "S-�-01" || smp.PointID != "P1" || len(smp.Measurements) != len(items) {
235			t.Fatalf("只应去掉首尾空白，实际为 %+v", smp)
236		}
237		gotItems := map[string]float64{}
238		for _, m := range smp.Measurements {
239			gotItems[m.Item] = m.Value
240		}
241		for _, m := range ms {
242			if gotItems[strings.TrimSpace(m.Item)] != m.Value {
243				t.Fatalf("项目名在返回记录中不一致: %+v", smp.Measurements)
244			}
245		}
246	
247		// 去首尾空白后相同仍是重复项目
248		if _, err := s.SubmitSample("S-dup", "P1", at(10, 0),
249			Measurement{Item: " pH ", Value: 1}, Measurement{Item: "pH", Value: 2}); !errors.Is(err, ErrDuplicateItem) {
250			t.Fatalf("去空白后相同的项目名仍属重复，got %v", err)
251		}
252	
253		// 含特殊字符的项目同样能按其名取到限值并完成确认
254		confirmed := mustConfirm(t, s, smp.ID)
