// 继续接受；只去首尾空白，不替换、不删除字符。登记成功返回的编号和名称与
// 保存内容一致，之后仍可用处理后的编号登记限值、录入样品并按点查看。
func TestRegisterPointAcceptsValidUnicodeText(t *testing.T) {
