		{"P-中文", "一号取水口"},      // 中文
		{"P\x001", "内 部 空 白"},    // 内部 U+0000 与内部空白
		{"P-emoji", "溶氧🫧"},       // 有效四字节字符
	}
	for _, c := range cases {
		p, err := s.RegisterPoint("  "+c.id+"  ", "  "+c.name+"  ")
		if err != nil {
			t.Fatalf("合法 Unicode 文本 %q 不应被拒绝: %v", c.id, err)
		}
		if p.ID != c.id || p.Name != c.name {
