	assertEncodingError(t, err, label)
	if errors.Is(err, ErrDuplicatePoint) {
		t.Fatalf("%s: 编码问题不能被归为重复编号: %v", label, err)
	}
	if got.ID != "" || got.Name != "" {
		t.Fatalf("%s: 失败必须返回编号、名称均为空的采样点，实际为 %+v", label, got)
	}
}

// 编号或名称含非法 UTF-8 字节时整次拒绝：末尾分别带孤立 0xFF、0xFE 的两个
